/* From Uiverse.io by vikramsinghnegi  - Tags: loading, active, switch, 2d button */
.__UIV_SCOPE__ .checkbox-wrap {
  display: block;
  width: 106px;
  height: 51px;
  position: relative;
  margin: 1px auto;
}
.__UIV_SCOPE__ #slide {
  display: block;
  width: 106px;
  height: 51px;
  margin: 0px;
  padding: 0px;
  position: absolute;
  z-index: 2;
  opacity: 0;
}
.__UIV_SCOPE__ #slide + label {
  display: block;
  width: 105px;
  height: 50px;
  margin: 0px;
  padding: 0px;
  z-index: 1;
  border-top: 1px solid transparent;
  border-left: 1px solid transparent;
}
.__UIV_SCOPE__ #pinkliquid {
  width: 88px;
  height: 36px;
  border-radius: 18px;
  margin: 7px 0 0 9px;
  overflow: hidden;
  background: #b4264a;
  background: linear-gradient(to bottom, #fe0744 0%, #ff0460 50%, #ff0082 100%);
  box-shadow: 0px 0px 9px 0px #ff1e00;
}
.__UIV_SCOPE__ .shine {
  width: 100%;
  background: rgba(255, 255, 255, 0.23);
  margin: 6px 0 4px 0;
  transition: all 300ms ease;
}
.__UIV_SCOPE__ .shine#shine-one {
  height: 12px;
}
.__UIV_SCOPE__ .shine#shine-two {
  height: 3px;
}
.__UIV_SCOPE__ #bubbles {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0px;
  left: 0px;
}
.__UIV_SCOPE__ #bubbles i {
  display: block;
  border-radius: 20px;
  background: #3a3236;
  position: absolute;
  transition: all 600ms ease;
}
.__UIV_SCOPE__ i#a {
  width: 4px;
  height: 4px;
  top: 35px;
  left: 19px;
}
.__UIV_SCOPE__ i#b {
  width: 5px;
  height: 5px;
  top: 24px;
  left: 30px;
}
.__UIV_SCOPE__ i#c {
  width: 3px;
  height: 3px;
  top: 15px;
  left: 26px;
}
.__UIV_SCOPE__ i#d {
  width: 6px;
  height: 6px;
  top: 20px;
  left: 40px;
}
.__UIV_SCOPE__ i#e {
  width: 5px;
  height: 5px;
  top: 30px;
  left: 33px;
}
.__UIV_SCOPE__ i#f {
  width: 5px;
  height: 5px;
  top: 30px;
  right: 33px;
}
.__UIV_SCOPE__ i#g {
  width: 6px;
  height: 6px;
  top: 20px;
  right: 40px;
}
.__UIV_SCOPE__ i#h {
  width: 3px;
  height: 3px;
  top: 15px;
  right: 26px;
}
.__UIV_SCOPE__ i#i {
  width: 4px;
  height: 4px;
  top: 35px;
  right: 19px;
}
.__UIV_SCOPE__ i#j {
  width: 5px;
  height: 5px;
  top: 24px;
  right: 30px;
}
.__UIV_SCOPE__ #circle {
  width: 37px;
  height: 37px;
  border-radius: 19px;
  background: #191919;
  position: absolute;
  top: 7px;
  left: 9px;
  border-right: 1px solid #e3006f;
  box-shadow: inset 0px 0px 10px 0px rgba(255, 255, 255, 0.24),
    0px 3px 4px 0px #000000;
  transition: all 300ms ease;
}
.__UIV_SCOPE__ #inner-circle {
  width: 31px;
  height: 31px;
  margin: 3px;
  border-radius: 16px;
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 0) 0%,
    rgba(255, 1, 122, 0.2) 100%
  );
}
.__UIV_SCOPE__ #slide:checked + label #circle {
  left: 60px;
  border-right: 1px solid transparent;
  border-left: 1px solid #e3006f;
  background-color: #c27098;
}
.__UIV_SCOPE__ #slide:checked + label #inner-circle {
  background: linear-gradient(
    to right,
    rgba(255, 1, 122, 0.2) 0%,
    rgba(0, 0, 0, 0) 100%
  );
}
.__UIV_SCOPE__ #slide:checked + label i#a {
  width: 4px;
  height: 4px;
  top: 26px;
  left: 19px;
}
.__UIV_SCOPE__ #slide:checked + label i#b {
  width: 5px;
  height: 5px;
  top: 24px;
  left: 30px;
}
.__UIV_SCOPE__ #slide:checked + label i#c {
  width: 3px;
