  top: 26px;
  right: 33px;
}
.__UIV_SCOPE__ #slide:checked + label i#g {
  width: 6px;
  height: 6px;
  top: 28px;
  right: 40px;
}
.__UIV_SCOPE__ #slide:checked + label i#h {
  width: 3px;
  height: 3px;
  top: 23px;
  right: 26px;
}
.__UIV_SCOPE__ #slide:checked + label i#i {
  width: 4px;
  height: 4px;
  top: 25px;
  right: 19px;
}
.__UIV_SCOPE__ #slide:checked + label i#j {
  width: 5px;
  height: 5px;
  top: 30px;
  right: 30px;
}
.__UIV_SCOPE__ #slide:checked + label .shine#shine-one {
  height: 12px;
  margin-top: 12px;
}
.__UIV_SCOPE__ #slide:checked + label .shine#shine-two {
  height: 3px;
  margin-top: -20px;
}
